"""Compare the slim imports to frozen results generated by the old environment.

The oracle is never generated by the implementation under test. See
nerfstudio_baseline.py and fixtures/nerfstudio_vendor/baseline.json.
"""
from __future__ import annotations

import ast
import hashlib
import json
import os
from pathlib import Path
import subprocess
import sys

import numpy as np
import pytest
import torch

from gsstudio._vendor.nerfstudio import colmap_parsing_utils as parser
from gsstudio._vendor.nerfstudio import colmap_utils, equirect_utils


FIXTURES = Path(__file__).resolve().parents[1]/'fixtures'/'nerfstudio_vendor'
VENDOR = Path(parser.__file__).parents[1]


def load(name):
    return json.loads((FIXTURES/name).read_text(encoding='utf-8'))


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def assert_records(actual, expected):
    assert list(map(str, actual)) == list(expected)
    for key, record in actual.items():
        reference = expected[str(key)]
        assert list(record._fields) == list(reference)
        for field in record._fields:
            value, target = getattr(record, field), reference[field]
            if isinstance(target, dict) and 'dtype' in target:
                assert isinstance(value, np.ndarray)
                assert value.dtype.str == target['dtype']
                assert list(value.shape) == target['shape']
                np.testing.assert_array_equal(value, np.array(target['data'], dtype=target['dtype']).reshape(target['shape']))
            else:
                assert value == target


def test_fixture_and_provenance_integrity():
    evidence = load('baseline.json')
    assert evidence['nerfstudio'] == '1.1.5'
    assert evidence['torch'] == '2.1.2+cu118'
    assert evidence['cuda_visible_devices'] == '-1'
    assert evidence['generator_sha256'] == digest(Path(__file__).with_name('nerfstudio_baseline.py'))
    for name, expected_hash in evidence['files'].items():
        assert digest(FIXTURES/name) == expected_hash, name
    provenance = json.loads((VENDOR/'provenance.json').read_text(encoding='utf-8'))
    for source in provenance['sources']:
        assert source['source_sha256'] == evidence['sources'][source['source']]
        target = VENDOR/source['vendored']
        assert digest(target) == source['vendored_sha256']
        content = target.read_text(encoding='utf-8')
        lines = content.splitlines(keepends=True)
        definitions = {node.name: node for node in ast.parse(content).body
                       if isinstance(node, (ast.FunctionDef, ast.ClassDef))}
        for symbol in source['symbols']:
            node = definitions[symbol['symbol']]
            excerpt = ''.join(lines[node.lineno-1:node.end_lineno]).rstrip()
            assert hashlib.sha256(excerpt.encode()).hexdigest() == symbol['normalized_source_sha256']
        if 'data_definitions_normalized_source_sha256' in source:
            excerpt = content[content.index('CameraModel = collections'):content.index('def read_next_bytes')].rstrip()
            assert hashlib.sha256(excerpt.encode()).hexdigest() == source['data_definitions_normalized_source_sha256']
    assert provenance['console_source']['source_sha256'] == evidence['sources']['utils/rich_utils.py']
    for license_record in provenance['licenses']:
        assert digest(VENDOR/license_record['file']) == license_record['sha256']
    bsd = (VENDOR/'LICENSE-COLMAP-BSD.txt').read_text(encoding='utf-8').rstrip()
    assert bsd in Path(parser.__file__).read_text(encoding='utf-8')


@pytest.mark.parametrize('kind', ['cameras', 'images', 'points3D'])
@pytest.mark.parametrize('suffix,extension', [('text', 'txt'), ('binary', 'bin')])
def test_all_colmap_record_fields_and_dtypes(kind, suffix, extension):
    actual = getattr(parser, f'read_{kind}_{suffix}')(FIXTURES/'parsing'/f'{kind}.{extension}')
    assert_records(actual, load('expected.json')[f'{kind}_{suffix}'])


def test_model_ids_namedtuple_fields_and_quaternion_orientation():
    expected = load('expected.json')
    assert [list(model) for model in sorted(parser.CAMERA_MODELS)] == expected['models']
    for name, fields in expected['fields'].items():
        assert list(getattr(parser, name)._fields) == fields
    for key, image in parser.read_images_binary(FIXTURES/'parsing'/'images.bin').items():
        np.testing.assert_array_equal(parser.qvec2rotmat(image.qvec), expected['rotations'][str(key)])
        np.testing.assert_array_equal(image.qvec2rotmat(), expected['rotations'][str(key)])
    np.testing.assert_array_equal(parser.qvec2rotmat(np.array([.8, .2, -.3, .45])), expected['nonunit_rotation'])


@pytest.mark.parametrize('model', [
    'SIMPLE_PINHOLE', 'PINHOLE', 'SIMPLE_RADIAL', 'RADIAL', 'OPENCV', 'OPENCV_FISHEYE',
    'FULL_OPENCV', 'FOV', 'SIMPLE_RADIAL_FISHEYE', 'RADIAL_FISHEYE', 'THIN_PRISM_FISHEYE', 'UNKNOWN',
])
def test_camera_intrinsics_distortion_and_unsupported_models(model):
    cameras = parser.read_cameras_binary(FIXTURES/'parsing'/'cameras.bin')
    camera = next((cam for cam in cameras.values() if cam.model == model), cameras[2]._replace(model=model))
    expected = load('expected.json')['camera_params'][model]
    if 'error' in expected:
        with pytest.raises(NotImplementedError) as caught:
            colmap_utils.parse_colmap_camera_params(camera)
        assert type(caught.value).__name__ == expected['error']
        assert str(caught.value) == expected['message']
    else:
        assert colmap_utils.parse_colmap_camera_params(camera) == expected['result']


@pytest.mark.parametrize('index', range(5))
def test_cpu_projection_against_old_torch_baseline(index):
    image = torch.from_numpy(np.load(FIXTURES/'projection-input.npy', allow_pickle=False))
    with pytest.warns(UserWarning, match='grid_sample'):
        actual = equirect_utils.equirect2persp(image, *load('projection-specs.json')[index]).numpy()
    with np.load(FIXTURES/'projection-results.npz', allow_pickle=False) as baseline:
        # CPU kernels may differ between Torch 2.1 and 2.8; source arithmetic is
        # separately audited verbatim. This bound is < 0.001 of an 8-bit level.
        np.testing.assert_allclose(actual, baseline[f'case_{index}'], rtol=0, atol=2e-6)
    assert actual.min() >= 0 and actual.max() <= 1


@pytest.mark.parametrize('index', range(6))
def test_transforms_json_world_axes_masks_depth_renames_and_ply(tmp_path, index):
    case = load('conversion-cases.json')[index]
    source = FIXTURES/'conversion'/case['name']
    options = dict(keep_original_world_coordinate=case['keep_original_world_coordinate'],
                   use_single_camera_mode=case['use_single_camera_mode'], ply_filename='synthetic-points.ply')
    if case['extras']:
        images = parser.read_images_binary(source/'model'/'images.bin')
        options.update(camera_mask_path=source/'masks'/'camera.png',
            image_id_to_depth_path={key: source/'depth'/f'{key}.png' for key in images},
            image_rename_map={image.name: f'renamed/{key}.jpg' for key, image in images.items()})
    assert colmap_utils.colmap_to_json(source/'model', tmp_path, **options) == case['count']
    assert (tmp_path/'transforms.json').read_bytes() == (source/'expected'/'transforms.json').read_bytes()
    assert (tmp_path/'synthetic-points.ply').read_bytes() == (source/'expected'/'sparse-ply.txt').read_bytes()


def test_pipeline_imports_and_cpu_conversion_with_nerfstudio_blocked(tmp_path):
    source_root = Path(__file__).resolve().parents[2]/'src'
    code = '''
import importlib.abc
import json
from pathlib import Path
import sys
class RejectNerfstudio(importlib.abc.MetaPathFinder):
    def find_spec(self, fullname, path=None, target=None):
        if fullname == 'nerfstudio' or fullname.startswith('nerfstudio.'):
            raise AssertionError('Top-level Nerfstudio import attempted: ' + fullname)
sys.meta_path.insert(0, RejectNerfstudio())
sys.path.insert(0, sys.argv[1])
from gsstudio.pipeline.reconstruction import core, colmap, realityscan
from gsstudio.pipeline.training import data
from gsstudio._vendor.nerfstudio import equirect_utils, colmap_utils
import torch
import warnings
fixtures, output = Path(sys.argv[2]), Path(sys.argv[3])
source = fixtures/'conversion'/'single_default'/'model'
realityscan.convert_colmap_text_to_binary(source, output/'model')
assert colmap_utils.colmap_to_json(output/'model', output, use_single_camera_mode=False) == 4
transforms = json.loads((output/'transforms.json').read_text())
for frame in transforms['frames']:
    mask = output/'masks'/(frame['file_path'].removeprefix('images/')+'.png')
    mask.parent.mkdir(parents=True, exist_ok=True)
    mask.write_bytes(b'synthetic mask inventory')
before = {p: p.read_bytes() for p in (output/'masks').rglob('*.png')}
core.attach_frame_masks(output/'transforms.json', output/'masks')
assert all(p.read_bytes() == value for p, value in before.items())
assert all(f['mask_path'].startswith('./masks/view_') for f in json.loads((output/'transforms.json').read_text())['frames'])
with warnings.catch_warnings():
    warnings.simplefilter('ignore', UserWarning)
    result = equirect_utils.equirect2persp(torch.zeros((1, 3, 18, 36)), 120, -180, 45, 12, 12)
assert result.device.type == 'cpu' and result.shape == (1, 3, 12, 12)
assert not any(name == 'nerfstudio' or name.startswith('nerfstudio.') for name in sys.modules)
print('CPU imports, projection, RealityScan conversion and mask attachment passed without Nerfstudio')
'''
    environment = dict(os.environ, CUDA_VISIBLE_DEVICES='-1', PYTHONDONTWRITEBYTECODE='1')
    result = subprocess.run([sys.executable, '-I', '-B', '-c', code, str(source_root), str(FIXTURES), str(tmp_path)],
                            env=environment, capture_output=True, text=True, encoding='utf-8', timeout=60)
    assert result.returncode == 0, result.stdout + result.stderr


def test_production_has_no_top_level_nerfstudio_import():
    source_root = Path(__file__).resolve().parents[2]/'src'
    for path in source_root.rglob('*.py'):
        for node in ast.walk(ast.parse(path.read_text(encoding='utf-8-sig'))):
            imports = ([node.module] if isinstance(node, ast.ImportFrom) and node.module else
                       [alias.name for alias in node.names] if isinstance(node, ast.Import) else [])
            assert not any(name == 'nerfstudio' or name.startswith('nerfstudio.') for name in imports), path
